import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';

import { Avatar, Badge, Button, Dropdown, Flex, type MenuProps, Typography } from 'antd';
import cn from 'classnames';

import ChatIcon from 'assets/images/icons/chat.svg?react';
import CommentIcon from 'assets/images/icons/comment.svg?react';
import DeleteIcon from 'assets/images/icons/delete.svg?react';
import DuplicateIcon from 'assets/images/icons/duplicate.svg?react';
import EditIcon from 'assets/images/icons/edit.svg?react';
import EyeIcon from 'assets/images/icons/eye.svg?react';
import MoreIcon from 'assets/images/icons/more.svg?react';
import MoveIcon from 'assets/images/icons/move.svg?react';
import SendIcon from 'assets/images/icons/send.svg?react';
import SmileIcon from 'assets/images/icons/smile.svg?react';
import { MOCK_IPost } from 'shared/consts/MOCK_FOR_CATALOG';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink } from 'shared/ui';
import { formatDate, formatNumber } from 'shared/utils';

import { DeletePostDrawer } from '../DeletePostDrawer/DeletePostDrawer';

import styles from './CollectionPostCard.module.scss';

interface ICollectionPostCardProps extends HTMLAttributes<HTMLDivElement> {
	post: MOCK_IPost;
	isPlanner?: boolean;
	isReport?: boolean;
}

export const CollectionPostCard: FC<ICollectionPostCardProps> = ({
	className,
	post,
	isPlanner,
	isReport,
	...props
}) => {
	const { description, image, name, id } = post;
	const { t } = useTranslation();
	const [expanded, setExpanded] = useState(false);
	const [isDeletePostDrawerOpen, setIsDeletePostDrawerOpen] = useState<boolean>(false);

	// 	TODO:
	const handleDuplicateClick = () => {};
	const handleMoveClick = () => {};
	const handleChatClick = () => {};
	const handleDeleteClick = () => {
		setIsDeletePostDrawerOpen(true);
	};
	const handleClick = () => {};

	const postActions: MenuProps['items'] = [
		{
			icon: <EditIcon />,
			key: 'edit',
			label: <Link to={`/${EMainRoutes.POST}/${id}`}>{t('Изменить')}</Link>,
		},
		{
			icon: <DuplicateIcon />,
			key: 'duplicate',
			label: t('Дублировать'),
			onClick: handleDuplicateClick,
		},
		{
			icon: <MoveIcon />,
			key: 'move',
			label: t('Переместить'),
			onClick: handleMoveClick,
		},
		{
			icon: <ChatIcon />,
			key: 'chat',
			label: t('Отправить в чат с ботом'),
			onClick: handleChatClick,
		},
		{
			danger: true,
			icon: <DeleteIcon />,
			key: 'delete',
			label: t('Удалить'),
			onClick: handleDeleteClick,
		},
	];

	return (
		<div {...props} className={cn(className, styles.collectionPostCard)}>
			<Flex gap={8} className={styles.collectionPostCard__info}>
				<Avatar
					shape="square"
					size={76}
					className={styles.collectionPostCard__img}
					icon={<img src={image} alt={name} />}
				/>
				<Typography.Paragraph
					className={styles.collectionPostCard__lineClamp}
					ellipsis={{
						rows: 4,
						expandable: 'collapsible',
						expanded,
						onExpand: (_, info) => setExpanded(info.expanded),
					}}>
					{description}
				</Typography.Paragraph>
			</Flex>
			<Flex
				gap={4}
				justify={'space-between'}
				className={cn(styles.collectionPostCard__part, styles.collectionPostCard__schedule)}>
				{post?.published_at ? (
					<Badge status="success" text={t('Опубликовано')} />
				) : (
					<Badge status="processing" text={t('Опубликуется')} />
				)}
				<Typography.Text type="secondary" style={{ fontSize: 12 }}>
					{formatDate(new Date(post.published_at || ''), 'long')}
				</Typography.Text>
			</Flex>
			{!isPlanner && !isReport && (
				<Flex gap={4} className={styles.collectionPostCard__part}>
					{/*TODO:*/}
					<Flex gap={8} align="center" className={styles.collectionPostCard__brand}>
						<Avatar
							shape="circle"
							size={32}
							className={styles.collectionPostCard__img}
							icon={<img src={image} alt={name} />}
						/>
						<Typography.Text ellipsis>Nike – Just do it today and tomorrow</Typography.Text>
					</Flex>
				</Flex>
			)}
			{!isPlanner && !isReport && (
				<Flex gap={4} className={styles.collectionPostCard__part}>
					<Dropdown menu={{ items: postActions }} trigger={['click']}>
						<Button style={{ flexShrink: 0 }} icon={<MoreIcon />} />
					</Dropdown>

					<ButtonStyleLink to={`/${EMainRoutes.POST}/${post.id}`} style={{ flexShrink: 0 }} icon={<SendIcon />} />

					<Button block onClick={handleClick}>
						{t('Запланировать пост')}
					</Button>
				</Flex>
			)}
			<DeletePostDrawer post={post} open={isDeletePostDrawerOpen} onClose={() => setIsDeletePostDrawerOpen(false)} />
			{(isPlanner || isReport) && post?.published_at && (
				<Flex
					gap={4}
					justify={'space-between'}
					className={cn(styles.collectionPostCard__part, styles.collectionPostCard__schedule)}>
					<Typography.Text type="secondary" style={{ fontSize: 12 }}>
						{t('Вовлеченность')}
					</Typography.Text>
					<Flex gap={12} align="center">
						<Flex gap={2} align="center">
							<Typography.Text type="secondary" style={{ lineHeight: 0 }}>
								<EyeIcon />
							</Typography.Text>
							<Typography.Text type="secondary" style={{ fontSize: 12, lineHeight: '12px' }}>
								{formatNumber(post.views_count || 0)}
							</Typography.Text>
						</Flex>
						<Flex gap={2} align="center">
							<Typography.Text type="secondary" style={{ lineHeight: 0 }}>
								<SmileIcon />
							</Typography.Text>
							<Typography.Text type="secondary" style={{ fontSize: 12, lineHeight: '12px' }}>
								{formatNumber(post.likes_count || 0)}
							</Typography.Text>
						</Flex>
						<Flex gap={2} align="center">
							<Typography.Text type="secondary" style={{ lineHeight: 0 }}>
								<CommentIcon />
							</Typography.Text>
							<Typography.Text type="secondary" style={{ fontSize: 12, lineHeight: '12px' }}>
								{formatNumber(post.comments_count || 0)}
							</Typography.Text>
						</Flex>
					</Flex>
				</Flex>
			)}
			{post.source && post.approved_amount && (
				<Flex gap={4} className={styles.collectionPostCard__part}>
					<div className={styles.report}>
						<Flex vertical>
							<Typography.Text style={{ fontSize: 12 }} strong>
								+ {post.approved_amount} РУБ
							</Typography.Text>
							<Typography.Text style={{ fontSize: 10 }} type="secondary">
								{t('Принес вам этот пост')}
							</Typography.Text>
						</Flex>
					</div>
					<div className={styles.report}>
						<Flex gap={8}>
							{post.source.logo_url && (
								<Avatar shape="circle" size={32} icon={<img src={post.source.logo_url} alt={post.source.name} />} />
							)}
							<Flex vertical>
								<Typography.Text style={{ fontSize: 12 }} strong>
									{post.source.name}
								</Typography.Text>
								<Typography.Text style={{ fontSize: 10 }} type="secondary">
									{formatNumber(post.source.subscribers_count || 0)}
								</Typography.Text>
							</Flex>
						</Flex>
					</div>
				</Flex>
			)}
		</div>
	);
};
