import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { DatePicker, Flex, Select } from 'antd';

import { EFilters, OPTIONS_MAX_HEIGHT_NOTIFICATIONS, useDateFilters, useFilters } from 'features/Filters';
import { useChannelOptions } from 'shared/hooks';

interface IReportsMainFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const ReportsMainFilters: FC<IReportsMainFiltersProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { getFilterValue, onFilterChange } = useFilters();
	const dateFromKey = EFilters.DATE_AFTER;
	const dateToKey = EFilters.DATE_BEFORE;

	const { dateAfter, dateBefore, onDatesChange } = useDateFilters(dateFromKey, dateToKey);
	const { channelOptions, isFetching } = useChannelOptions();

	return (
		<Flex {...props} vertical gap={8}>
			<Select
				value={getFilterValue(EFilters.SOURCE) || t('Все каналы и группы')}
				options={channelOptions}
				onChange={(value) => onFilterChange(EFilters.SOURCE, value)}
				placeholder={t('Выберите каналы')}
				size="large"
				showSearch
				optionFilterProp="search"
				allowClear
				listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
				style={{ width: '100%' }}
				loading={isFetching}
				disabled={isFetching}
			/>

			<DatePicker.RangePicker
				size="large"
				format="DD.MM.YYYY"
				value={[dateAfter, dateBefore]}
				style={{ minWidth: 230 }}
				onChange={(value) => {
					onDatesChange(value, [dateFromKey, dateToKey]);
				}}
			/>
		</Flex>
	);
};
