import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Column } from '@ant-design/plots';

import { Button, Flex, theme, Typography } from 'antd';

import ChartIcon from 'assets/images/icons/chart.svg?react';
import { useStatisticsChartListQuery } from 'entities/Report';
import { EFilters, getUrlParamsForApi, ReportsEarningsFilters, useFilters } from 'features/Filters';
import { OverlayLoader } from 'shared/ui';

import styles from './EarningsChart.module.scss';

interface IEarningsChartProps extends HTMLAttributes<HTMLDivElement> {}

export const EarningsChart: FC<IEarningsChartProps> = ({ ...props }) => {
	const { t } = useTranslation();

	const [searchParams] = useSearchParams();
	const { data, isFetching } = useStatisticsChartListQuery(getUrlParamsForApi(searchParams));

	const {
		token: { colorPrimary, colorPrimaryBorder, colorTextDescription },
	} = theme.useToken();

	const chartSize = window.innerWidth > 480 ? 480 : window.innerWidth - 12;

	const { getFilterValue } = useFilters();

	const period = getFilterValue(EFilters.AGGREGATE_BY) || 'day';
	const earningsType = getFilterValue(EFilters.EARNINGS_TYPE) || 'payments';

	if (!data || data?.length === 0) return null;

	const getDate = (date: string) => {
		const dates = {
			day: new Date(date).toLocaleString('ru-RU', { day: '2-digit', month: '2-digit' }),
			month: new Date(date).toLocaleString('ru-RU', { month: 'short' }),
			year: new Date(date).toLocaleString('ru-RU', { year: 'numeric' }),
		};
		return dates[period as keyof typeof dates];
	};
	const chartData = [
		...data.map((item) => ({
			date: getDate(item.date),
			value: Number(earningsType === 'payments' ? item.approved_amount : item.approved_actions_count),
			type: 'approved',
		})),
		...data.map((item) => ({
			date: getDate(item.date),
			value: Number(earningsType === 'payments' ? item.pending_amount : item.actions_count),
			type: 'pending',
		})),
	];

	const config = {
		data: chartData,
		xField: 'date',
		yField: 'value',
		colorField: 'type',
		stack: true,
		axis: {
			x: {
				labelFill: colorTextDescription,
			},
			y: {
				labelFill: colorTextDescription,
			},
		},
		legend: false,
		style: {
			inset: 1,
			radiusTopLeft: 4,
			radiusTopRight: 4,
			radiusBottomLeft: 4,
			radiusBottomRight: 4,
			fill: ({ type }: { type: string }) => {
				const colors = {
					approved: colorPrimary,
					pending: colorPrimaryBorder,
				};
				return colors[type as keyof typeof colors] || colorPrimary;
			},
		},
	};

	return (
		<Flex {...props} vertical gap={12}>
			{isFetching && <OverlayLoader />}

			<ReportsEarningsFilters />

			<div className={styles.chart}>
				<Column width={chartSize} height={chartSize} {...config} className={styles.chart} />
			</div>

			<Flex gap={12} className={styles.legend}>
				<Flex align="center" gap={10}>
					<div className={styles.square} style={{ backgroundColor: colorPrimary }}></div>
					<Typography.Text type="secondary" className={styles.legendText}>
						{earningsType === 'payments' ? `${t('Выплачено')}, РУБ` : t('Подтверждено')}
					</Typography.Text>
				</Flex>

				<Flex align="center" gap={10}>
					<div className={styles.square} style={{ backgroundColor: colorPrimaryBorder }}></div>
					<Typography.Text type="secondary" className={styles.legendText}>
						{earningsType === 'payments' ? `${t('Ожидают подтверждения')}, РУБ` : t('Ожидают подтверждения')}
					</Typography.Text>
				</Flex>
			</Flex>

			<Button variant="outlined" color="primary" size="large" icon={<ChartIcon />} iconPosition="end">
				{t('Запросить полную статистику')}
			</Button>
		</Flex>
	);
};
